(function(root){
 'use strict';
 function render(options,progress,{esc,fmt,img,button}){
  const forms=options.forms||[],mons=options.mons||[],unlocked=options.unlocked||[];
  const capacity=progress.capacity,used=progress.used,next=progress.next;
  const formFor=mon=>forms.find(form=>(form.key||form.id)===mon.megaKey);
  const compatible=mon=>forms.filter(form=>unlocked.includes(form.key||form.id)&&(form.base===mon.id||form.baseId===mon.id));
  const nextView=next?`<section class="um-unlock"><div><h4>Mở ô Mega thứ ${fmt(next.capacity)}</h4><p>${fmt(next.badges)} huy hiệu · ${fmt(next.shards)} mảnh Mega</p><small>${next.missingBadges||next.missingShards?[next.missingBadges?`Cần thêm ${fmt(next.missingBadges)} huy hiệu`:'',next.missingShards?`Thiếu ${fmt(next.missingShards)} mảnh Mega`:''].filter(Boolean).join(' · '):'Đã đủ điều kiện. Mở một lần, dùng vĩnh viễn.'}</small></div>${button(`Mở ô thứ ${fmt(next.capacity)}`,'unlock-mega-slot',`data-capacity="${next.capacity}"`,!next.available,'um-unlock-button')}</section>`:'<p class="um-max">Đã mở đủ 6 ô Mega.</p>';
  return `<section class="um-root" aria-label="Trang bị Mega"><header class="um-head"><div><h3>Đội hình Mega</h3><p>${fmt(used)} / ${fmt(capacity)} ô đang dùng</p></div><span class="um-shards">${img('assets/umi/mega-shard.svg')}<b>${fmt(progress.shards)}</b> mảnh Mega</span></header><div class="um-slots" aria-label="${fmt(used)} trên ${fmt(capacity)} ô Mega đang dùng">${Array.from({length:6},(_,index)=>`<span class="${index<used?'is-used':index<capacity?'is-open':'is-locked'}">${index<used?'Mega':index<capacity?'Trống':'Khóa'}<small>Ô ${index+1}</small></span>`).join('')}</div><p class="um-rule">Ô đầu tiên miễn phí. Mở thêm bằng huy hiệu đạo quán và mảnh Mega.</p>${nextView}<details class="um-roadmap"><summary>Các mốc mở ô · ${fmt(progress.badges)} huy hiệu đang có</summary><ol>${(progress.milestones||[]).filter(step=>step.capacity>1).map(step=>`<li><b>Ô ${fmt(step.capacity)}</b><span>${fmt(step.badges)} huy hiệu · ${fmt(step.shards)} mảnh Mega${step.capacity<=capacity?' · Đã mở':''}</span></li>`).join('')}</ol><p class="um-details-note">Ô Mega dùng chung cho bộ sưu tập. Pokémon ở PC, nhà trẻ và đang làm nhiệm vụ vẫn chiếm ô. Hai Charizard khác nhau có thể cùng dùng Mega X.</p><p class="um-details-note">Trang bị Mega tự bật Giữ lại bản trùng cho gia đình Pokémon đó.</p></details><section class="um-team"><h4>Chọn Pokémon trang bị</h4>${used>=capacity?'<p class="um-full">Muốn thêm Pokémon Mega, tháo một con hoặc mở ô tiếp theo. Pokémon đã trang bị vẫn đổi dạng được.</p>':''}<div class="um-mon-list">${mons.map(mon=>{const current=formFor(mon),choices=compatible(mon),blocked=!mon.megaKey&&used>=capacity;return `<article class="um-mon">${img(mon.icon)}<div class="um-mon-copy"><h4>${esc(mon.name)}</h4><small>Cấp ${fmt(mon.level)}</small><p>${current?`Đang dùng ${esc(current.name)}`:'Chưa trang bị Đá Mega'}</p>${!choices.length?'<small>Chưa mở khóa dạng Mega tương thích.</small>':blocked?'<small>Đã dùng hết ô Mega.</small>':''}</div><div class="um-mon-actions">${button(mon.megaKey?'Đổi dạng':'Trang bị','equip',`data-uid="${esc(mon.uid)}"`,blocked||!choices.length)}${mon.megaKey?button('Tháo','unequip',`data-uid="${esc(mon.uid)}"`):''}</div></article>`}).join('')||'<p class="ua-empty">Chưa có Pokémon phù hợp trong bộ sưu tập.</p>'}</div></section><details class="um-catalog"><summary>Bộ sưu tập Đá Mega · ${fmt(unlocked.length)} / ${fmt(forms.length)} dạng đã mở</summary><p>Mở ô và mở khóa dạng Mega là hai tiến độ riêng. Dùng Vé chọn Đá Mega để mở dạng bạn muốn.</p><div class="um-catalog-list">${forms.map(form=>`<article>${img(form.icon||form.src)}<div><b>${esc(form.name)}</b><small>${unlocked.includes(form.key||form.id)?'Đã mở khóa':'Chưa mở khóa'}</small></div></article>`).join('')}</div></details></section>`;
 }
 root.UmiMegaUI={render};
})(globalThis);
